                  initial={{ width: 0 }}
                  animate={{ width: `${step.progress}%` }}
                  className="h-full rounded-full bg-gradient-to-r from-violet-500 to-cyan-500"
                />
              </div>
            )}
          </motion.div>
        ))}
      </div>
    </motion.div>
