import { motion, AnimatePresence } from 'framer-motion'
import type { ThinkingStep } from '../lib/api'

interface Props {
  stats?: { total_raw: number; total_deduped: number; engines: Record<string, number> }
  steps?: ThinkingStep[]
  isActive?: boolean
}

export default function SearchRadar({ stats, steps, isActive }: Props) {
  if (!stats && (!steps || steps.length === 0)) return null

  const engines = Object.entries(stats?.engines || {})
  const currentStep = steps?.[steps.length - 1]
  const progress = currentStep?.progress || 0

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="rounded-xl border border-slate-700/50 bg-slate-900/80 p-4 mb-4 overflow-hidden"
    >
      {/* Progress bar */}
      <div className="relative h-1 rounded-full bg-slate-800 mb-3 overflow-hidden">
        <motion.div
          initial={{ width: 0 }}
          animate={{ width: `${progress}%` }}
          transition={{ duration: 0.5, ease: 'easeOut' }}
          className="absolute inset-y-0 left-0 rounded-full bg-gradient-to-r from-violet-500 via-cyan-500 to-emerald-500"
        />
        {isActive && (
          <motion.div
            animate={{ x: ['0%', '200%'] }}
            transition={{ duration: 1.5, repeat: Infinity, ease: 'linear' }}
            className="absolute inset-y-0 w-1/3 bg-gradient-to-r from-transparent via-white/20 to-transparent"
          />
        )}
      </div>

      {/* Current phase */}
      <div className="flex items-center gap-2 mb-3">
        {isActive ? (
          <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
        ) : (
          <div className="w-2 h-2 rounded-full bg-emerald-400" />
        )}
        <span className="text-xs font-medium text-slate-300">
          {currentStep?.step || '搜索引擎矩阵'}
        </span>
        {stats && (
          <span className="text-xs text-slate-500 ml-auto">
            {stats.total_deduped} 条数据
          </span>
        )}
      </div>

      {/* Engine status list */}
      <AnimatePresence>
        {engines.length > 0 && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            className="flex flex-wrap gap-1.5"
          >
            {engines.map(([name, count], idx) => (
              <motion.span
                key={name}
                initial={{ scale: 0, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                transition={{ delay: idx * 0.08, type: 'spring', stiffness: 300 }}
                className="px-2 py-1 rounded-md text-[10px] bg-slate-800 border border-slate-700/50 text-slate-400 flex items-center gap-1"
              >
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                {name}
                <span className="text-emerald-400 font-medium">{count}</span>
              </motion.span>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Thinking steps timeline */}
      {steps && steps.length > 1 && (
        <div className="mt-3 pt-3 border-t border-slate-800/50 space-y-1">
          {steps.slice(-4).map((step, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, x: -8 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: i * 0.05 }}
              className="flex items-center gap-2 text-[10px]"
            >
              <span className={`w-1 h-1 rounded-full ${
                i === steps.slice(-4).length - 1 && isActive
                  ? 'bg-violet-400 animate-pulse'
                  : 'bg-slate-600'
              }`} />
              <span className="text-slate-500">{step.step}</span>
              <span className="text-slate-600 truncate">{step.detail}</span>
            </motion.div>
          ))}
        </div>
      )}
    </motion.div>
  )
}

import { motion } from 'framer-motion'

interface Props {
  engines?: Record<string, number>
  totalResults?: number
  isActive?: boolean
  count?: number
}

export default function DataUniverseParticles({ engines, totalResults, isActive, count }: Props) {
  const total = totalResults || count || 0
  if (total === 0 && !engines) return null

  const engineEntries = Object.entries(engines || {})
  const maxCount = Math.max(...engineEntries.map(([, c]) => c), 1)

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      className="rounded-xl border border-slate-700/50 bg-slate-900/80 p-4 mb-3 overflow-hidden relative"
    >
      {/* Ambient glow */}
      {isActive && (
        <motion.div
          animate={{ opacity: [0.1, 0.3, 0.1] }}
          transition={{ duration: 2, repeat: Infinity }}
          className="absolute inset-0 bg-gradient-to-br from-cyan-500/5 via-transparent to-violet-500/5 pointer-events-none"
        />
      )}

      <div className="flex items-center gap-2 mb-3 relative">
        <motion.div
          animate={isActive ? { scale: [1, 1.2, 1] } : {}}
          transition={{ duration: 1.5, repeat: Infinity }}
          className="w-2 h-2 rounded-full bg-cyan-400"
        />
        <span className="text-xs font-medium text-slate-300">数据收集</span>
        <motion.span
          key={total}
          initial={{ scale: 1.3, color: '#22d3ee' }}
          animate={{ scale: 1, color: '#94a3b8' }}
          className="text-xs text-slate-400 ml-auto font-mono"
        >
          {total} 条
        </motion.span>
      </div>

      {/* Engine bars */}
      {engineEntries.length > 0 && (
        <div className="space-y-1.5 relative">
          {engineEntries.map(([name, cnt], idx) => (
            <motion.div
              key={name}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: idx * 0.1, type: 'spring', stiffness: 200 }}
              className="flex items-center gap-2"
            >
              <span className="text-[10px] text-slate-500 w-20 truncate">{name}</span>
              <div className="flex-1 h-1.5 rounded-full bg-slate-800 overflow-hidden">
                <motion.div
                  initial={{ width: 0 }}
                  animate={{ width: `${(cnt / maxCount) * 100}%` }}
                  transition={{ delay: idx * 0.1 + 0.2, duration: 0.6, ease: 'easeOut' }}
                  className="h-full rounded-full bg-gradient-to-r from-cyan-500 to-violet-500"
                />
              </div>
              <span className="text-[10px] text-cyan-400 font-mono w-6 text-right">{cnt}</span>
            </motion.div>
          ))}
        </div>
      )}

      {/* Particle dots animation */}
      {isActive && (
        <div className="flex justify-center gap-1 mt-3 pt-2 border-t border-slate-800/50">
          {[...Array(7)].map((_, i) => (
            <motion.span
              key={i}
              animate={{
                y: [0, -4, 0],
                opacity: [0.3, 1, 0.3],
              }}
              transition={{ duration: 1.2, delay: i * 0.1, repeat: Infinity }}
              className="w-1 h-1 rounded-full bg-cyan-400"
            />
          ))}
        </div>
      )}
    </motion.div>
  )
}

import { motion } from 'framer-motion'
import type { GraphNode, GraphData } from '../lib/api'

interface Props {
  node: GraphNode | null
  graphData?: GraphData
  onClose?: () => void
  onExpand?: (node: GraphNode) => void
  isExpanding?: boolean
}

export default function GraphDetailPanel({ node, graphData, onClose, onExpand, isExpanding }: Props) {
  if (!node) return null

  const connectedNodes = graphData?.links
    .filter(l => {
      const src = typeof l.source === 'string' ? l.source : (l.source as any).id
      const tgt = typeof l.target === 'string' ? l.target : (l.target as any).id
      return src === node.id || tgt === node.id
    })
    .map(l => {
      const src = typeof l.source === 'string' ? l.source : (l.source as any).id
      const otherId = src === node.id
        ? (typeof l.target === 'string' ? l.target : (l.target as any).id)
        : src
      const otherNode = graphData?.nodes.find(n => n.id === otherId)
      return { label: l.label, node: otherNode }
    })
    .filter(x => x.node) || []

  return (
    <motion.div
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: 20 }}
      className="w-64 shrink-0 rounded-xl border border-slate-700/50 bg-slate-900/95 backdrop-blur-xl p-4 shadow-xl self-start sticky top-4"
    >
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <span className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: node.color }} />
          <span className="text-sm font-medium text-slate-200 truncate">{node.name}</span>
        </div>
        {onClose && (
          <button onClick={onClose} className="text-xs text-slate-500 hover:text-slate-300 transition-colors p-1">
            ✕
          </button>
        )}
      </div>

      <div className="flex items-center gap-2 mb-3">
        <span className="text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-500 border border-slate-700/30">
          {node.type}
        </span>
        <span className="text-[10px] text-slate-600">权重: {node.val}</span>
      </div>

      {node.desc && (
        <p className="text-xs text-slate-400 mb-3 leading-relaxed">{node.desc}</p>
      )}

      {connectedNodes.length > 0 && (
        <div className="mb-3">
          <p className="text-[10px] text-slate-500 font-medium mb-1.5">关联节点 ({connectedNodes.length})</p>
          <div className="space-y-1 max-h-32 overflow-y-auto">
            {connectedNodes.slice(0, 8).map((conn, i) => (
              <div key={i} className="flex items-center gap-1.5 text-[10px]">
                <span className="w-1.5 h-1.5 rounded-full shrink-0" style={{ backgroundColor: conn.node!.color }} />
                <span className="text-slate-400 truncate">{conn.node!.name}</span>
                <span className="text-slate-600 ml-auto shrink-0">{conn.label}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {onExpand && (
        <button
          onClick={() => onExpand(node)}
          disabled={isExpanding}
          className="w-full text-xs px-3 py-2 rounded-lg bg-violet-600/20 border border-violet-500/30 text-violet-300 hover:bg-violet-600/30 disabled:opacity-50 transition-colors flex items-center justify-center gap-1.5"
        >
          {isExpanding ? (
            <>
              <motion.span animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}>⟳</motion.span>
              扩展中...
            </>
          ) : (
            <>🔍 深入探索此节点</>
          )}
        </button>
      )}
    </motion.div>
  )
}

import { motion } from 'framer-motion'
import { Search, GitBranch, FileText } from 'lucide-react'

interface Props {
  phase: 'idle' | 'searching' | 'graphing' | 'reporting' | 'done'
  progress?: number
}

const PHASES = [
  { key: 'searching', label: '搜索中', icon: Search, color: 'from-cyan-500 to-blue-500' },
  { key: 'graphing', label: '构建图谱', icon: GitBranch, color: 'from-violet-500 to-purple-500' },
  { key: 'reporting', label: '生成报告', icon: FileText, color: 'from-emerald-500 to-teal-500' },
] as const

export default function AIProgressBar({ phase, progress = 0 }: Props) {
  if (phase === 'idle' || phase === 'done') return null

  const phaseIndex = PHASES.findIndex(p => p.key === phase)

  return (
    <motion.div
      initial={{ opacity: 0, y: -10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className="px-4 py-2 border-b border-slate-800/50"
    >
      <div className="max-w-3xl mx-auto">
        {/* Phase indicators */}
        <div className="flex items-center gap-1 mb-2">
          {PHASES.map((p, i) => {
            const Icon = p.icon
            const isActive = i === phaseIndex
            const isDone = i < phaseIndex

            return (
              <div key={p.key} className="flex items-center gap-1 flex-1">
                <motion.div
                  animate={isActive ? { scale: [1, 1.1, 1] } : {}}
                  transition={{ duration: 1.5, repeat: Infinity }}
                  className={`flex items-center gap-1.5 px-2 py-1 rounded-md text-[10px] font-medium transition-all ${
                    isActive
                      ? 'bg-slate-800 border border-slate-700/50 text-slate-200'
                      : isDone
                        ? 'text-emerald-400'
                        : 'text-slate-600'
                  }`}
                >
                  <Icon className="w-3 h-3" />
                  <span>{p.label}</span>
                  {isDone && <span className="text-emerald-400">✓</span>}
                </motion.div>
                {i < PHASES.length - 1 && (
                  <div className={`flex-1 h-px ${isDone ? 'bg-emerald-500/50' : 'bg-slate-800'}`} />
                )}
              </div>
            )
          })}
        </div>

        {/* Progress bar with shimmer */}
        <div className="relative h-0.5 rounded-full bg-slate-800 overflow-hidden">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${progress}%` }}
            transition={{ duration: 0.3, ease: 'easeOut' }}
            className={`absolute inset-y-0 left-0 rounded-full bg-gradient-to-r ${PHASES[phaseIndex]?.color || 'from-cyan-500 to-blue-500'}`}
          />
          <motion.div
            animate={{ x: ['-100%', '200%'] }}
            transition={{ duration: 2, repeat: Infinity, ease: 'linear' }}
            className="absolute inset-y-0 w-1/4 bg-gradient-to-r from-transparent via-white/30 to-transparent"
          />
        </div>
      </div>
    </motion.div>
  )
}

